% Input data
int: num_digits = 4;

% Decision Variables
array[1..num_digits] of var 0..9: pin;

% Extract individual digits for easier manipulation
var 0..9: a = pin[1];
var 0..9: b = pin[2];
var 0..9: c = pin[3];
var 0..9: d = pin[4];

% Constraints
constraint alldifferent(pin); % No two digits are the same

% The 2-digit number cd is 3 times the 2-digit number ab
constraint 10*c + d = 3*(10*a + b);

% The 2-digit number da is 2 times the 2-digit number bc
constraint 10*d + a = 2*(10*b + c);

% Additional constraints to ensure valid 2-digit numbers
constraint a != 0; % ab is a 2-digit number
constraint b != 0 \/ a != 0; % ab is a 2-digit number (relaxed)
constraint c != 0 \/ a != 0; % Not strictly necessary but for clarity on cd being a 2-digit number when a != 0
constraint d != 0 \/ b != 0; % da and bc being 2-digit numbers when b != 0 and d != 0

solve satisfy;

output [
    "{",
    join(",", [
        "\"a\": " ++ show(a),
        "\"b\": " ++ show(b),
        "\"c\": " ++ show(c),
        "\"d\": " ++ show(d)
    ]),
    "}"
];
