% Input data
int: n = 20;  % total number of steps
int: m1 = 3;  % minimum steps at a time
int: m2 = 5;  % maximum steps at a time
int: max_moves = n;  % maximum number of moves

% Decision Variables
array[1..max_moves] of var 0..m2: steps;
var int: num_moves;

% Constraints
constraint num_moves <= max_moves;
constraint sum(i in 1..num_moves) (steps[i]) = n;
constraint forall(i in 1..num_moves) (steps[i] >= m1 /\ steps[i] <= m2);
constraint forall(i in num_moves+1..max_moves) (steps[i] = 0);
constraint num_moves > 0;

% Define the bounds for num_moves
constraint num_moves >= n div m2;
constraint num_moves <= n div m1;

solve satisfy;

output [
    "{",
    "\"steps\": " ++ show(steps),
    "}"
];
```

