array[Children] of string: child_names = ["Bernice", "Carl", "Debby", "Sammy", "Ted"];
array[Children] of string: countries = ["Ethiopia", "Kazakhstan", "Lithuania", "Morocco", "Yemen"];
array[Children] of string: stories = ["burning bush", "captivity", "Moses's youth", "Passover", "the Ten Commandments"];
array[1..num_children] of int: ages = [3, 5, 7, 8, 10];

% Decision Variables
array[Children] of var 1..num_children: child;
array[Children] of var 1..num_children: country;
array[Children] of var 1..num_children: story;
array[Children] of var 1..num_children: age;

% Constraints
constraint alldifferent(child);
constraint alldifferent(country);
constraint alldifferent(story);
constraint alldifferent(age);

% 1. Debby's family is from Lithuania.
constraint country[3] = 3;

% 2. The child who told the story of the Passover is two years older than Bernice.
constraint exists(i in Children) (
    story[i] = 4 /\ 
    exists(j in Children) (
        child[j] = 1 /\ 
        age[i] = age[j] + 2
    )
);

% 3. The child whose family is from Yemen is younger than the child from the Ethiopian family.
constraint exists(i in Children) (
    country[i] = 5 /\ 
    exists(j in Children) (
        country[j] = 1 /\ 
        age[i] < age[j]
    )
);

% 4. The child from the Moroccan family is three years older than Ted.
constraint exists(i in Children) (
    country[i] = 4 /\ 
    exists(j in Children) (
        child[j] = 5 /\ 
        age[i] = age[j] + 3
    )
);

% 5. Sammy is three years older than the child who told the story of Moses's youth in the house of the Pharaoh.
constraint exists(i in Children) (
    child[i] = 4 /\ 
    exists(j in Children) (
        story[j] = 3 /\ 
        age[i] = age[j] + 3
    )
);

solve satisfy;

output [
    "{",
    "\"ages\": " ++ show([age[i] | i in Children]) ++ ", ",
    "\"children\": " ++ show([child[i] | i in Children]) ++ ", ",
    "\"countries\": " ++ show([country[i] | i in Children]) ++ ", ",
    "\"stories\": " ++ show([story[i] | i in Children]),
    "}"
];
