include "globals.mzn";

% Number of cows
int: num_cows = 25;
% Number of sons
int: num_sons = 5;

% Distribution of cows to sons
array[1..num_sons] of int: distribution = [7, 6, 5, 4, 3];

% Milk production per cow
array[1..num_cows] of int: milk_production = [i | i in 1..num_cows];

% Decision variable: assignment of cows to sons
array[1..num_cows] of var 0..num_sons-1: cow_assignments;

% Constraints
constraint global_cardinality(cow_assignments, [i | i in 0..num_sons-1], distribution);

% Calculate milk production per son
array[0..num_sons-1] of var int: milk_per_son;
constraint global_cardinality(cow_assignments, [i | i in 0..num_sons-1], [milk_per_son[i] | i in 0..num_sons-1]);
constraint sum([milk_production[i] * bool2int(cow_assignments[i] = s) | i in 1..num_cows]) = milk_per_son[s] /\ s in 0..num_sons-1;

% All sons should have the same total milk production
constraint all_equal(milk_per_son);

solve satisfy;

output [
    "{",
    "\"cow_assignments\": ", show([cow_assignments[i] | i in 1..num_cows]),
    "}"
];
```

