constraint total_fuel = sum([if s[i] != i then conso[i, s[i]] else 0 endif | i in 1..nbHouses]);

constraint total_fuel <= fuelMax; % do not exceed the fuel limit

% Objective function
solve maximize total_gold;

% Output
output [
    "{",
    "\"s\": ", show([s[i] | i in 1..nbHouses]),
    "}"
];
