% Input data
int: num_people = 3;
array[1..num_people] of string: names;

% Decision Variables
array[1..num_people] of var 1..num_people: hates;
array[1..num_people] of var bool: richer;
var 1..num_people: killer;

% Constraints
% Agatha hates everybody except the butler
constraint hates[1] = 2;
constraint forall(i in 1..num_people where i != 2) (hates[1] != i);

% The butler hates everyone not richer than Aunt Agatha
constraint forall(i in 1..num_people) (richer[i] = false -> hates[2] = i);

% The butler hates everyone whom Agatha hates
constraint forall(i in 1..num_people) ((hates[1] = i) -> (hates[2] = i));

% Charles hates noone that Agatha hates
constraint forall(i in 1..num_people) ((hates[1] = i) -> (hates[3] != i));

% A killer always hates, and is no richer than his victim (Agatha, index 1)
constraint hates[killer] = 1;
constraint richer[killer] = false;

% Noone hates everyone
constraint forall(i in 1..num_people) (sum(j in 1..num_people) (bool2int(hates[i] = j)) < num_people);

% The killer must be one of the people in the mansion
constraint killer >= 1 /\ killer <= num_people;

% Agatha is not richer than herself
constraint richer[1] = true;

% Solve the model
solve satisfy;

% Output the solution
output [
    "{",
    "\"" ++ "killer" ++ "\": " ++ show(killer),
    "}"
];
```

