include "globals.mzn";

% Data
set of int: Houses = 1..5;
set of string: Colors = {"yellow", "green", "red", "white", "blue"};
set of string: Nations = {"italy", "spain", "japan", "england", "norway"};
set of string: Pets = {"cat", "zebra", "bear", "snails", "horse"};
set of string: Drinks = {"milk", "water", "tea", "coffee", "juice"};
set of string: Jobs = {"painter", "sculptor", "diplomat", "pianist", "doctor"};

% Variables
array[Houses] of var Colors: color;
array[Houses] of var Nations: nation;
array[Houses] of var Pets: pet;
array[Houses] of var Drinks: drink;
array[Houses] of var Jobs: job;

% Constraints
constraint alldifferent([color[h] | h in Houses]);
constraint alldifferent([nation[h] | h in Houses]);
constraint alldifferent([pet[h] | h in Houses]);
constraint alldifferent([drink[h] | h in Houses]);
constraint alldifferent([job[h] | h in Houses]);

% the painter owns the horse
constraint forall (h in Houses) (job[h] = "painter" -> pet[h] = "horse");

% the diplomat drinks coffee
constraint forall (h in Houses) (job[h] = "diplomat" -> drink[h] = "coffee");

% the one who drinks milk lives in the white house
constraint forall (h in Houses) (drink[h] = "milk" -> color[h] = "white");

% the Spaniard is a painter
constraint forall (h in Houses) (nation[h] = "spain" -> job[h] = "painter");

% the Englishman lives in the red house
constraint forall (h in Houses) (nation[h] = "england" -> color[h] = "red");

% the snails are owned by the sculptor
constraint forall (h in Houses) (pet[h] = "snails" -> job[h] = "sculptor");

% the green house is on the left of the red one
constraint forall (h in 1..4) (color[h] = "green" -> color[h+1] = "red");

% the Norwegian lives on the right of the blue house
constraint exists(h in 2..5) (nation[h] = "norway" /\ color[h-1] = "blue");

% the doctor drinks milk
constraint forall (h in Houses) (job[h] = "doctor" -> drink[h] = "milk");

% the diplomat is Japanese
constraint forall (h in Houses) (job[h] = "diplomat" -> nation[h] = "japan");

% the Norwegian owns the zebra
constraint forall (h in Houses) (nation[h] = "norway" -> pet[h] = "zebra");

% the green house is next to the white one
constraint forall (h in 1..4) ((color[h] = "green" /\ color[h+1] = "white") \/ (color[h] = "white" /\ color[h+1] = "green"));

% the horse is owned by the neighbor of the diplomat
constraint forall (h in Houses) (job[h] = "diplomat" -> 
                                (if h > 1 then (pet[h-1] = "horse") else false endif \/ 
                                 if h < 5 then (pet[h+1] = "horse") else false endif));

% the Italian either lives in the red, white or green house
constraint forall (h in Houses) (nation[h] = "italy" -> (color[h] = "red" \/ color[h] = "white" \/ color[h] = "green"));

% Additional constraint to fix milk in the middle house
constraint drink[3] = "milk";

solve satisfy;

output [
    "{",
    join(",", [
        "\"colors\": " ++ show([index_set(Colors, color[h]) | h in Houses]),
        "\"nations\": " ++ show([index_set(Nations, nation[h]) | h in Houses]),
        "\"jobs\": " ++ show([index_set(Jobs, job[h]) | h in Houses]),
        "\"pets\": " ++ show([index_set(Pets, pet[h]) | h in Houses]),
        "\"drinks\": " ++ show([index_set(Drinks, drink[h]) | h in Houses])
    ]),
    "}"
];
