include "globals.mzn";

% Input data
int: num_car_types = 6;
int: num_options = 5;
array[1..num_options] of int: at_most;
array[1..num_options] of int: per_slots;
array[1..num_car_types] of int: demand;
array[1..num_car_types, 1..num_options] of int: requires;

% Calculate total number of cars
int: total_cars = sum(demand);

% Decision Variables
array[1..total_cars] of var 1..num_car_types: sequence;

% Constraints
constraint global_cardinality(sequence, 1..num_car_types, demand);

% For each option, ensure that the capacity is not exceeded
constraint forall(option in 1..num_options) (
    forall(i in 1..total_cars - per_slots[option] + 1) (
        sum(j in i..i + per_slots[option] - 1) (requires[sequence[j], option]) <= at_most[option]
    )
);

% Redundant constraint to improve propagation: check the total number of cars requiring each option
constraint forall(option in 1..num_options) (
    sum(car_type in 1..num_car_types) (demand[car_type] * requires[car_type, option]) <= 
    max(at_most[option] * (total_cars div per_slots[option]) + 
        min(at_most[option], total_cars mod per_slots[option]), 
        sum(i in 1..total_cars) (requires[sequence[i], option]))
);

solve satisfy;

output [
    "{",
    "\"sequence\": ", show([sequence[i] - 1 | i in 1..total_cars]), 
    "}"
];
```

