% Input data
int: n = 10;  % Length of the binary sequence

% Decision Variables
array[1..n] of var -1..1: sequence;

% Constraints
constraint forall(i in 1..n) (sequence[i] != 0);  % Ensuring sequence[i] is either -1 or 1

% Function to compute the k-th autocorrelation with periodic boundary conditions
function var int: C(int: k) = 
    sum(i in 1..n) (sequence[i] * sequence[(i + k - 1) mod n + 1]);

% Computing the energy E
var int: E = sum(k in 1..n-1) (C(k) * C(k));

% Objective: Minimize the energy E
solve minimize E;

% Output the solution in JSON format
output [
    "{",
    "\"sequence\": ", show([sequence[i] | i in 1..n]), ", ",
    "\"E\": ", show(E),
    "}"
];
```

