array[1..n_containers] of var 0..deck_length: top;
array[1..n_containers] of var 0..deck_length: bottom;
array[1..n_containers] of var bool: is_placed;

% Constraints
constraint forall (c in 1..n_containers) (
    left[c] + width[c] = right[c] /\ 
    bottom[c] + length[c] = top[c] /\ 
    left[c] >= 0 /\ right[c] <= deck_width /\
    bottom[c] >= 0 /\ top[c] <= deck_length /\
    is_placed[c] = (left[c] < right[c] /\ bottom[c] < top[c])
);

constraint forall (c1, c2 in 1..n_containers where c1 < c2) (
    not (is_placed[c1] /\ is_placed[c2]) \/
    (left[c1] >= right[c2] \/ left[c2] >= right[c1] \/ 
     bottom[c1] >= top[c2] \/ bottom[c2] >= top[c1])
);

constraint forall (c1, c2 in 1..n_containers where c1 != c2 /\ classes[c1] != classes[c2]) (
    let {
        int: class1 = classes[c1];
        int: class2 = classes[c2];
        int: sep_x = separation[class1, class2];
        int: sep_y = separation[class1, class2]; % Assuming same separation for x and y
    } in
    not (is_placed[c1] /\ is_placed[c2]) \/
    (left[c1] >= right[c2] + sep_x \/ left[c2] >= right[c1] + sep_x \/
     bottom[c1] >= top[c2] + sep_y \/ bottom[c2] >= top[c1] + sep_y)
);

constraint forall (c in 1..n_containers) (
    (left[c] = 0 \/ exists (c2 in 1..n_containers where c2 != c) (right[c2] = left[c])) /\
    (bottom[c] = 0 \/ exists (c2 in 1..n_containers where c2 != c) (top[c2] = bottom[c]))
);

solve satisfy;

output [
