% Input data
int: n_weeks = 4;  % Number of weeks
int: n_groups = 3;  % Number of groups
int: group_size = 3;  % Size of each group
int: n_golfers = n_groups * group_size;  % Total number of golfers

% Decision Variables
array[1..n_weeks, 1..n_groups, 1..group_size] of var 1..n_golfers: assign;

% Constraints
constraint forall (w in 1..n_weeks) (
    forall (g in 1..n_groups) (
        all_different([assign[w, g, s] | s in 1..group_size])
    )
);

constraint forall (g1 in 1..n_groups, g2 in 1..n_groups, s1 in 1..group_size, s2 in 1..group_size, w1 in 1..n_weeks, w2 in 1..n_weeks where (w1 < w2)) (
    (assign[w1, g1, s1] = assign[w2, g2, s2] -> (g1 = g2 /\ s1 = s2))
);

constraint all_different([assign[1, g, s] | g in 1..n_groups, s in 1..group_size]);

constraint forall (g in 1..n_groups, s in 1..group_size, w in 1..n_weeks) (
    assign[w, g, s] >= 1 /\ assign[w, g, s] <= n_golfers
);

% Redundant constraint to ensure each golfer plays exactly once per week
constraint forall (w in 1..n_weeks, golfer in 1..n_golfers) (
    sum([bool2int(assign[w, g, s] = golfer) | g in 1..n_groups, s in 1..group_size]) = 1
);

solve satisfy;

output [
    "{",
    "\"assign\": [",
    join(",", [
        "[" ++ join(",", [
            "[" ++ join(",", [show(assign[w, g, s]) | s in 1..group_size]) ++ "]"
            | g in 1..n_groups
        ]) ++ "]"
        | w in 1..n_weeks
    ]),
    "]",
    "}"
];
