% Input data
int: n_teams = 9;
int: n_days = 18;

% Teams and days
set of int: TEAMS = 1..n_teams;
set of int: DAYS = 1..n_days;

% Mirroring scheme
array[DAYS] of int: mirror = [8, 9, 12, 13, 14, 15, 16, 1, 2, 17, 18, 3, 4, 5, 6, 7, 10, 11];

% Decision Variables
array[TEAMS, DAYS] of var -1..n_teams: opponent;
array[TEAMS, DAYS] of var 0..2: where; % 0: away, 1: home, 2: bye

% Constraints
constraint forall(t in TEAMS, d in DAYS) (
    if where[t, d] = 2 then opponent[t, d] = -1 else 
    if where[t, d] = 1 then opponent[t, d] = t else 
    opponent[t, d] != t
    endif endif
);

constraint forall(t1 in TEAMS, t2 in TEAMS, d in DAYS where t1 != t2) (
    (opponent[t1, d] = t2 /\ where[t1, d] = 1) <-> (opponent[t2, d] = t1 /\ where[t2, d] = 0)
);

constraint forall(t in TEAMS) (
    forall(d in 1..n_days-1) (
        (where[t, d] = 0 /\ where[t, d+1] = 0) -> where[t, d+2] != 0 /\
        (where[t, d] = 1 /\ where[t, d+1] = 1) -> where[t, d+2] != 1
    ) /\
    forall(d in 1..n_days-2) (
        count([where[t, d], where[t, d+1], where[t, d+2]], 0, c) /\ c <= 2 /\
        count([where[t, d], where[t, d+1], where[t, d+2]], 2, c) /\ c <= 1 /\
        count([where[t, d], where[t, d+1], where[t, d+2]], 1, c) /\ c <= 2
    )
);

constraint forall(t in TEAMS) (
    let { int: count_home = sum([bool2int(where[t, d] = 1) | d in {2, 4, 6, 8, 10, 12, 14, 16}]); 
          int: count_away = sum([bool2int(where[t, d] = 0) | d in {2, 4, 6, 8, 10, 12, 14, 16}]); 
          int: count_bye = sum([bool2int(where[t, d] = 2) | d in {2, 4, 6, 8, 10, 12, 14, 16}]) } 
    in count_home = 4 /\ count_away = 4 /\ count_bye = 1
);

constraint forall(t in TEAMS) (
    sum([bool2int(where[t, d] = 1 \/ where[t, d] = 2) | d in {2, 4, 6, 8, 10}]) >= 2
);

constraint forall(d in {11..18}) (
    (opponent[4, d] = 6 \/ opponent[6, d] = 4) /\
    (opponent[4, d] = 2 \/ opponent[2, d] = 4) /\
    (opponent[3, d] = 6 \/ opponent[6, d] = 3) /\
    (opponent[3, d] = 2 \/ opponent[2, d] = 3)
);

constraint forall(t in TEAMS, d in 1..n_days-1) (
    (opponent[t, d] = 6 /\ where[t, d] = 0 /\ opponent[t, d+1] = 2 /\ where[t, d+1] = 0) -> false /\
    (opponent[t, d] = 2 /\ where[t, d] = 0 /\ opponent[t, d+1] = 6 /\ where[t, d+1] = 0) -> false
);

constraint forall(t in TEAMS, d in 1..n_days-2) (
    (opponent[t, d] = 6 /\ where[t, d] = 0 /\ opponent[t, d+1] = 2 /\ where[t, d+1] = 0 /\ opponent[t, d+2] = 8 /\ where[t, d+2] = 0) -> false /\
