include "globals.mzn";

% Input data
int: rows = 8;  % Number of rows
int: cols = 13;  % Number of columns
int: row_rule_len = 2;  % Maximum length of row rules
int: col_rule_len = 2;  % Maximum length of column rules
array[1..rows, 1..row_rule_len] of int: row_rules;  % Rules for rows
array[1..cols, 1..col_rule_len] of int: col_rules;  % Rules for columns

% Decision Variables
array[1..rows, 1..cols] of var 0..1: board;  % The solution board

% Constraints for rows
constraint forall(r in 1..rows) (
    sequence([board[r, c] | c in 1..cols], row_rules[r])
);

% Constraints for columns
constraint forall(c in 1..cols) (
    sequence([board[r, c] | r in 1..rows], col_rules[c])
);

% Predicate to model the sequence constraint for nonogram rules
predicate sequence(array[int] of var int: x, array[int] of int: rules) =
    let {
        int: n = length(x);
        int: nr = length(rules);
        array[1..nr] of var int: starts;
        array[1..nr] of var int: lens;
    } in
    forall(i in 1..nr) (
        lens[i] = rules[i] /\ 
        starts[i] >= 1 /\ starts[i] + lens[i] - 1 <= n /\
        (i > 1 -> starts[i] > starts[i-1] + lens[i-1]) /\
        forall(j in starts[i]..starts[i] + lens[i] - 1) (x[j] = 1) /\
        (i < nr -> starts[i] + lens[i] <= starts[i+1]) /\
        (starts[i] > 1 -> x[starts[i]-1] = 0) /\
        (starts[i] + lens[i] <= n -> x[starts[i] + lens[i]] = 0)
    );

% Solve the model
solve satisfy;

% Output the solution in JSON format
output [
    "{",
    "\"board\": [",
    join(",\n", [show([board[r, c] | c in 1..cols]) | r in 1..rows]),
    "]}"
];
```

