include "globals.mzn";

% Input data
int: n_boats = 5;  % Number of boats
int: n_periods = 4;  % Number of periods
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];  % Capacities of the boats
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];  % Crew sizes of the boats

% Decision Variables
array[1..n_boats] of var bool: is_host;  % Whether a boat is a host
array[1..n_boats, 1..n_boats, 1..n_periods] of var bool: visits;  % Visit schedule

% Constraints
% A boat cannot visit itself
constraint forall(b in 1..n_boats, p in 1..n_periods) (
    visits[b, b, p] = false
);

% If a boat is not a host, it must visit a host in each period
constraint forall(b1 in 1..n_boats, p in 1..n_periods) (
    not is_host[b1] -> (sum([visits[b1, b2, p] | b2 in 1..n_boats where is_host[b2]]) = 1)
);

% If a boat is a host, it cannot visit any other boat
constraint forall(b1 in 1..n_boats, p in 1..n_periods) (
    is_host[b1] -> (sum([visits[b1, b2, p] | b2 in 1..n_boats]) = 0)
);

% The total number of people on a host boat should not exceed its capacity
constraint forall(b2 in 1..n_boats, p in 1..n_periods) (
    is_host[b2] -> (sum([visits[b1, b2, p] * crew_size[b1] | b1 in 1..n_boats]) + crew_size[b2] <= capacity[b2])
);

% A guest boat cannot revisit a host
constraint forall(b1 in 1..n_boats, b2 in 1..n_boats) (
    not is_host[b1] /\ is_host[b2] -> (sum([visits[b1, b2, p] | p in 1..n_periods]) <= 1)
);

% Guest crews cannot meet more than once
constraint forall(b1 in 1..n_boats, b3 in 1..n_boats, b2 in 1..n_boats where b1 < b3 /\ is_host[b2]) (
    sum([visits[b1, b2, p] /\ visits[b3, b2, p] | p in 1..n_periods]) <= 1
);

% Symmetry breaking: sort the is_host array
constraint increasing([is_host[i] | i in 1..n_boats]);

% Solve to minimize the number of host boats
solve minimize sum(is_host);

% Output the solution
output [
    "{",
    "\"visits\": ", show([[[bool2int(visits[b1, b2, p]) | p in 1..n_periods] | b2 in 1..n_boats] | b1 in 1..n_boats]), ", ",
    "\"is_host\": ", show([bool2int(is_host[b]) | b in 1..n_boats]),
    "}"
];
```

