include "globals.mzn";

% Input data
int: k = 4;  % Number of sets
int: n = 4;  % Numbers from 1 to n

% Derived data
int: total_numbers = k * n;
int: total_positions = 2 * k * n;

% Decision Variables
array[1..total_numbers] of var 1..total_positions: sequence;
array[1..n] of var 1..total_positions: position;

% Constraints
constraint all_different(sequence);

constraint forall (i in 1..n) (
    let {
        array[1..k] of var int: occurrences = [index(sequence, i, o) | o in 1..k];
    } in
        position[i] = min(occurrences) /\ 
        forall (o1, o2 in 1..k where o1 != o2) (
            sequence[occurrences[o1]] + i = sequence[occurrences[o2]]
        )
);

constraint forall (i in 1..total_numbers) (
    sequence[i] >= 1 /\ sequence[i] <= total_positions
);

constraint all_different(sequence);

% Redundant constraint to improve performance
constraint forall (i in 1..n) (
    position[i] + i <= total_positions
);

% Solve
solve satisfy;

% Output
output [
    "{",
    "\"position\": [" ++ join(", ", [show(position[i]) | i in 1..n]) ++ "],",
    "\"solution\": [" ++ join(", ", [show(sequence[i]) | i in 1..total_numbers]) ++ "]",
    "}"
];
