include "globals.mzn";

% Input data
int: n = 8;  % Number of words to find
int: word_length = 8;
set of int: WordIndex = 1..n;
set of int: PositionIndex = 1..word_length;
set of int: Alphabet = 1..4;  % A, C, G, T

% Mapping for Watson-Crick complement
array[Alphabet] of int: complement = [4, 3, 2, 1];  % A=1 -> T=4, C=2 -> G=3, G=3 -> C=2, T=4 -> A=1

% Decision Variables
array[WordIndex, PositionIndex] of var Alphabet: words;
var int: num_words;

% Constraints
constraint num_words = n;

% Each word has 4 symbols from {C, G}
constraint forall(w in WordIndex) (
    sum(p in PositionIndex) (words[w, p] = 2 \/ words[w, p] = 3) = 4
);

% Each pair of distinct words differ in at least 4 positions
constraint forall(w1, w2 in WordIndex where w1 < w2) (
    sum(p in PositionIndex) (words[w1, p] != words[w2, p]) >= 4
);

% Each pair of words x and y (where x and y may be identical) are such that x^R and y^C differ in at least 4 positions
constraint forall(w1, w2 in WordIndex) (
    sum(p in PositionIndex) (words[w1, word_length-p+1] != complement[words[w2, p]]) >= 4
);

solve maximize num_words;

% Output the set of words
array[1..4] of string: alphabet_map = ["A", "C", "G", "T"];

output [
    "{\n",
    "    \"words\": [",
    join(",\n        ", [
        "\"" ++ join("", [alphabet_map[words[w, p]] | p in PositionIndex]) ++ "\""
        | w in 1..num_words
    ]),
    "]\n",
    "}"
];
```

