% Steiner Triple Systems
include "globals.mzn";

% Input data
int: n = 9;  % Order of the Steiner Triple System

% Calculate the number of triples
int: num_triples = n * (n-1) div 6;

% Decision Variables
array[1..num_triples] of var set of 1..n: triples;

% Constraints
constraint forall (t in 1..num_triples) (
    card(triples[t]) = 3
);

constraint forall (i, j in 1..num_triples where i < j) (
    card(triples[i] intersect triples[j]) <= 1
);

constraint forall (e in 1..n) (
    (sum(t in 1..num_triples) (bool2int(e in triples[t]))) = (n-1) div 2
);

% Check if n is valid for Steiner Triple System
constraint (n mod 6 = 1) \/ (n mod 6 = 3);

solve satisfy;

output [
    "{",
    "\"sets\": [",
    join(",", [show(triples[t]) | t in 1..num_triples]),
    "]",
    "}"
];
