    array3d(1..8, 1..8, 1..8, 
            [| [i * j * k | k in factors] | j in factors] | i in factors);

% Find the combinations that result in a product of 36
set of tuple(int, int, int): valid_combinations = 
    { <factors[i], factors[j], factors[k]> | i in 1..8, j in 1..8, k in 1..8 where products[i, j, k] = 36 };

