% Number of dice and faces per die
int: num_dice = 5;
int: num_faces = 6;

% Decision Variables: the faces of the dice
array[1..num_dice, 1..num_faces] of var 1..num_faces*num_dice: dice;

% Constraints: each die has distinct faces
constraint forall(d in 1..num_dice) (
    alldifferent([dice[d, f] | f in 1..num_faces])
);

% Constraints: the 'beats' relationships between the dice
constraint forall(i in 1..num_faces) (
    sum(d in {1,4}) (dice[1, i] > dice[d, i]) >= 4
);
constraint forall(i in 1..num_faces) (
    sum(d in {2,5}) (dice[2, i] > dice[d, i]) >= 4
);
constraint forall(i in 1..num_faces) (
    sum(d in {3,4}) (dice[3, i] > dice[d, i]) >= 4
);
constraint forall(i in 1..num_faces) (
    sum(d in {2,1}) (dice[4, i] > dice[d, i]) >= 4
);
constraint forall(i in 1..num_faces) (
    sum(d in {3,5}) (dice[5, i] > dice[d, i]) >= 4
);

% Constraints: the dice are ordered (symmetry breaking)
constraint forall(d in 1..num_dice-1) (
    dice[d,1] < dice[d+1,1]
);

% Solve the problem
solve satisfy;

% Output the solution
output [
    "{",
    "\"dice\": ", show([ [dice[d,f] | f in 1..num_faces] | d in 1..num_dice ]),
    "}"
];
