% Constraints
constraint alldifferent([x[i, j] | i in 1..n, j in 1..n]);

% Define the possible movements
var 1..n*n: first;
constraint x[1,1] = first;

constraint forall(i in 1..n*n-1) (
    let {
        var 1..n: x1; var 1..n: y1; var 1..n: x2; var 1..n: y2;
        array[1..n, 1..n] of var bool: b;
    } in
        % Find the coordinates of the current and next number
        sum([bool2int(x[p, q] = i) * p | p in 1..n, q in 1..n]) = x1 /\
        sum([bool2int(x[p, q] = i) * q | p in 1..n, q in 1..n]) = y1 /\
        sum([bool2int(x[p, q] = i+1) * p | p in 1..n, q in 1..n]) = x2 /\
        sum([bool2int(x[p, q] = i+1) * q | p in 1..n, q in 1..n]) = y2 /\

        % Check if the movement is valid
        ( ( (x1 - x2 == 0 /\ abs(y1 - y2) == 3) \/ 
            (y1 - y2 == 0 /\ abs(x1 - x2) == 3) ) 
