        % Ensure that the next number is within the grid
        x2 >= 1 /\ x2 <= n /\ y2 >= 1 /\ y2 <= n
);

% Redundant constraint to improve performance
constraint first = 1;

solve satisfy;

output [
    "{",
    "\"x\": [",
    join(",\n", [
        join(",", [show(x[i, j]) | j in 1..n]) | i in 1..n
    ]),
