% Define the possible values for the players and nationalities
set of int: Players = 0..2;
set of int: Nationalities = 0..2;

% Decision Variables: 
% x, y, z represent the nationalities of players X, Y, Z respectively
var Nationalities: x;
var Nationalities: y;
var Nationalities: z;

% american, english, french represent the players who are American, English, French respectively
var Players: american;
var Players: english;
var Players: french;

% Constraints
constraint all_different([x, y, z]);
constraint all_different([american, english, french]);

% Y passed three hearts to the American
constraint y != american;

% X passed the queen of spades and two diamonds to the person who passed their cards to the Frenchwoman
constraint x != french;
constraint (x + 1) mod 3 == french \/ (x + 2) mod 3 == french; % The person on X's right is either (x+1) or (x+2) mod 3

% The person who received cards from X passed their cards to the Frenchwoman
% So, the person on X's right is either Y or Z, and they passed their cards to the Frenchwoman
constraint ((x + 1) mod 3 == y /\ y != french) \/ ((x + 2) mod 3 == y /\ y != french);
constraint ((x + 1) mod 3 == z /\ z != french) \/ ((x + 2) mod 3 == z /\ z != french);

% Y is not French because Y passed cards to the American
constraint y != french;

% Linking the players with their nationalities
constraint (x == american /\ (x + 1) mod 3 == y \/ x == english /\ (x + 1) mod 3 == z) -> (y == french \/ z == french);
constraint (x == american /\ (x + 2) mod 3 == y \/ x == english /\ (x + 2) mod 3 == z) -> (y == french \/ z == french);
constraint (x == american /\ (x + 1) mod 3 == z \/ x == english /\ (x + 1) mod 3 == y) -> (y == french \/ z == french);
constraint (x == american /\ (x + 2) mod 3 == z \/ x == english /\ (x + 2) mod 3 == y) -> (y == french \/ z == french);

% Since Y passed to American, and X passed to either Y or Z, we need to ensure the correct linking
constraint (y == american -> (x == english \/ x == french)) /\ (y != american -> (x != english /\ x != french));

solve satisfy;

output [
    "{",
    join(",", [
        "\"x\": " ++ show(x),
        "\"y\": " ++ show(y),
        "\"z\": " ++ show(z),
        "\"american\": " ++ show(american),
        "\"english\": " ++ show(english),
        "\"french\": " ++ show(french)
    ]),
    "}"
];
