constraint x[1] = 12;

% Calculate the sum of every triplet of adjacent numbers
array[1..n] of var int: sums;
constraint forall(i in 1..n) (
    sums[i] = x[i] + x[(i mod n) + 1] + x[((i+1) mod n) + 1]
);

% Find the maximum sum
constraint maximum(max_sum, sums);

% The maximum sum should not exceed 21
constraint max_sum <= 21;

solve satisfy;

output [
    "{",
    "\"x\": [",
    join(", ", [show(x[i]) | i in 1..n]),
    "]}"
];
