array[1..num_warehouses] of int: fixed_costs = [400, 500, 300, 150];  % Weekly fixed costs per warehouse
int: max_shipping = 100;  % Max units per week per warehouse
array[1..num_regions] of int: demands = [80, 70, 40];  % Weekly demands for regions 1 to 3
array[1..num_warehouses, 1..num_regions] of int: shipping_costs = 
    [| 20, 40, 50 |
     | 48, 15, 26 |
     | 26, 35, 18 |
     | 24, 50, 35 |];

% Decision Variables
array[1..num_warehouses] of var bool: open_warehouse;  % Whether each warehouse is open
array[1..num_warehouses, 1..num_regions] of var 0..max_shipping: ships;  % Shipping quantity from warehouse to region

% Constraints
constraint sum(open_warehouse) <= 3;  % No more than three warehouses can be operational
constraint open_warehouse[1] -> open_warehouse[2];  % If New York is open, Los Angeles must be open
constraint open_warehouse[2] \/ open_warehouse[4];  % Either Los Angeles or Atlanta must be open
constraint forall(r in 1..num_regions)(
    sum(w in 1..num_warehouses)(ships[w, r]) = demands[r]  % Meet demands for each region
);
constraint forall(w in 1..num_warehouses, r in 1..num_regions)(
    ships[w, r] <= max_shipping * bool2int(open_warehouse[w])  % Shipping limit per warehouse
);

% Objective function
var int: total_cost = sum(w in 1..num_warehouses)(fixed_costs[w] * bool2int(open_warehouse[w])) + 
                      sum(w in 1..num_warehouses, r in 1..num_regions)(shipping_costs[w, r] * ships[w, r]);

solve minimize total_cost;

output [
    "{",
