    "\"open_warehouse\": [" ++ join(", ", [show(bool2int(open_warehouse[w])) | w in 1..num_warehouses]) ++ "], ",
    "\"ships\": [",
    join(", ", [
        "[" ++ join(", ", [show(ships[w, r]) | r in 1..num_regions]) ++ "]" | w in 1..num_warehouses
    ]),
    "]",
    "}"
];
