include "globals.mzn";

% Input data
int: num_coins = length(init);
int: num_moves;
array[1..num_coins] of int: init;

% Decision Variables
array[1..num_moves, 1..num_coins] of var 0..1: coins;
array[1..num_moves] of var 1..num_coins: steps;

% Initial configuration
constraint coins[1,1..num_coins] = init;

% Transition constraints
constraint forall(m in 1..num_moves-1) (
    forall(i in 1..num_coins) (
        if i = steps[m] then 
            coins[m+1, i] = 1 - coins[m, i]
        else 
            coins[m+1, i] = coins[m, i]
        endif
    )
);

% Flip one coin per move
constraint forall(m in 1..num_moves) (
    sum(i in 1..num_coins) (
        if i = steps[m] then 1 else 0 endif
    ) = 1
);

% Final state is either all heads or all tails
constraint forall(i in 1..num_coins-1) (
    coins[num_moves, i] = coins[num_moves, i+1]
);

% Steps should be valid (i.e., within the range of coins)
constraint forall(m in 1..num_moves) (
    1 <= steps[m] /\ steps[m] <= num_coins
);

solve satisfy;

output [
    "{",
    "\"steps\": ", show([steps[i] | i in 1..num_moves]),
    "}"
];
```

